var rows=global.get('mcSim_writeBuffer')||[];
var lastWritten=global.get('mcSim_lastWritten')||{};
try{
    var payload=typeof msg.payload==='string'?JSON.parse(msg.payload):msg.payload;
    var nodeId=payload.node_id||0;
    var myNodeId=global.get('mcSim_nodeId')||0;
    if(myNodeId&&nodeId!==myNodeId){node.status({fill:'grey',shape:'dot',text:'Skip foreign '+nodeId});return null;}
    var deviceId=payload.device_id||0;
    var deviceName=payload.device_name||'';
    var hostPcIp=payload.host_pc_ip||'';
    var ts=payload.ts||new Date().toISOString();
    var changed=0;var skipped=0;var now=Date.now();

    (payload.values||[]).forEach(function(v){
        var tagId=v.tag_id||0;var tagAddr=v.tag_address||'';
        if(!tagId&&!tagAddr){skipped++;return;}
        var key=nodeId+'_'+deviceId+'_'+tagId+'_'+tagAddr;
        var last=lastWritten[key];
        var raw=v.raw_value;
        var eng=v.eng_value;
        var q=v.quality||0;
        if(last&&now-last.ts<1000){skipped++;return;}
        if(last&&String(last.raw)===String(raw)&&String(last.eng)===String(eng)&&String(last.q)===String(q)){skipped++;return;}
        lastWritten[key]={raw:raw,eng:eng,q:q,ts:now};
        changed++;
        rows.push({
            ts:ts, node_id:nodeId, device_id:deviceId, device_name:deviceName,
            tag_id:tagId, tag_address:tagAddr, tag_name:v.tag_name||'',
            raw_value:raw, eng_value:eng, unit:v.unit||'',
            quality:q, host_pc_ip:hostPcIp
        });
    });

    if(rows.length>50000){
        node.warn('[Buffer] Overflow! Drop oldest 5000 rows');
        rows=rows.slice(-45000);
    }

    // 条目数上限: 超5万删最旧1万, 防千级点位内存泄漏
    var keys=Object.keys(lastWritten);
    if(keys.length>50000){
        keys.sort(function(a,b){return (lastWritten[a].ts||0)-(lastWritten[b].ts||0);});
        for(var i=0;i<10000;i++){delete lastWritten[keys[i]];}
        node.warn('[Buffer] lastWritten overflow, purged 10000 oldest keys');
    }

    global.set('mcSim_lastWritten',lastWritten);
    global.set('mcSim_writeBuffer',rows);
    node.status({fill:'green',shape:'dot',text:changed+' new / '+skipped+' skip / '+rows.length+' total'});
}catch(e){
    node.warn('[Buffer] Parse error: '+e.message);
}
return null;

var pg=global.get('pg');
if(!pg){node.warn('[PG] pg not available');return null;}

var retryBuf=global.get('mcSim_retryBuffer')||[];
var mainBuf=global.get('mcSim_writeBuffer')||[];
if(retryBuf.length===0&&mainBuf.length===0){node.status({fill:'grey',shape:'dot',text:'idle'});return null;}

// 忙锁 + 10s超时兜底
if(global.get('mcSim_pgWriting')){return null;}
global.set('mcSim_pgWriting',true);
var lockTimer=setTimeout(function(){global.set('mcSim_pgWriting',false);node.warn('[PG] force release lock after 10s');},10000);

// 原子替换缓冲
global.set('mcSim_retryBuffer',[]);global.set('mcSim_writeBuffer',[]);
var batch=retryBuf.concat(mainBuf);

// 1000行分批
if(batch.length>1000){
    var remaining=batch.slice(1000);
    batch=batch.slice(0,1000);
    var currentMain=global.get('mcSim_writeBuffer')||[];
    global.set('mcSim_writeBuffer',remaining.concat(currentMain));
}

if(batch.length===0){global.set('mcSim_pgWriting',false);return null;}

// 构建批量INSERT
var valStrs=[];var params=[];var idx=0;
batch.forEach(function(r){
    var vals=[r.ts,r.node_id,r.device_id,r.device_name,
              r.tag_id,r.tag_address,r.tag_name,
              r.raw_value,r.eng_value,r.unit,r.quality,r.host_pc_ip];
    var ph=[];
    vals.forEach(function(v){idx++;ph.push('$'+idx);params.push(v===undefined?null:v);});
    valStrs.push('('+ph.join(',')+')');
});

var sql='INSERT INTO edgelink.plc_data (insert_time,node_id,device_id,device_name,tag_id,tag_address,tag_name,raw_value,eng_value,unit,quality,host_pc_ip) VALUES '+valStrs.join(',');

// 连接池复用, 配置变了自动重建(全字段对比)
var pool=global.get('mcSim_pgPool');
var wanted={host:'127.0.0.1',port:5432,database:'postgres',user:'postgres',password:'',max:5};
var wantedStr=JSON.stringify(wanted);
var currentStr=pool&&pool.options?JSON.stringify({host:pool.options.host,port:pool.options.port,database:pool.options.database,user:pool.options.user,password:pool.options.password}):'';
if(pool&&currentStr!==wantedStr){
    if(global.get('mcSim_debug'))node.warn('[Pool] Config changed, rebuilding');
    try{pool.end();}catch(e2){}
    pool=null;global.set('mcSim_pgPool',null);
}
if(!pool){
    pool=new pg.Pool(wanted);
    pool.on('error',function(e){node.warn('[Pool] '+e.message);global.set('mcSim_pgPool',null);});
    global.set('mcSim_pgPool',pool);
}

node.status({fill:'yellow',shape:'dot',text:'Writing '+batch.length+'...'});

pool.query({text:sql,values:params}).then(function(result){
    clearTimeout(lockTimer);
    node.status({fill:'green',shape:'dot',text:(result.rowCount||batch.length)+' OK'});
    global.set('mcSim_pgWriting',false);
}).catch(function(e){
    clearTimeout(lockTimer);
    node.warn('[PG] write failed: '+e.message);
    var rb=global.get('mcSim_retryBuffer')||[];
    var merged=batch.concat(rb);
    if(merged.length>20000){node.warn('[PG] retryBuffer overflow! Keep latest 20000, drop '+(merged.length-20000));merged=merged.slice(-20000);}
    global.set('mcSim_retryBuffer',merged);
    node.status({fill:'red',shape:'ring',text:'PG FAIL'});
    global.set('mcSim_pgWriting',false);
});

return null;
